				method: "POST",
				headers: {
					"Content-Type": "application/json",
				},
				body: JSON.stringify(item.payload),
			});

			if (res.ok) {
				await db.sync_queue.update(item.id!, { status: "completed" });
			} else {
				await db.sync_queue.update(item.id!, { status: "failed" });
